```ts
function render(state: State) {
  switch (state.status) {
    case "loading":
      return spinner();
    case "error":
      return alert(state.error);
    case "success":
      return table(state.data);
    default: {
      const eksik: never = state; // yeni durum eklenirse burada patlar
      return eksik;
    }
  }
}
